const manual={enabled:true,index:0,history:[],message:'',pending:null};
const movePanel=el('section',{class:'panel manual-tools','aria-label':'Manual part placement'});
movePanel.innerHTML='<div class="sectionhead"><label class="move-toggle"><input id="move-mode" type="checkbox"> Move parts</label></div><p class="hint">After optimizing, drag a piece on this sheet, or select it and enter an exact position in cm. Arrow keys move 1 mm; Shift + arrow moves 1 cm.</p><div id="move-fields"><label>Part<select id="move-part"></select></label><label>X (cm)<input id="move-x" type="number" min="0" step="0.1"></label><label>Y (cm)<input id="move-y" type="number" min="0" step="0.1"></label><button id="apply-move">Move</button></div><div class="tool-buttons"><button id="undo-move">Undo move</button><button id="reset-layout">Reset to automatic layout</button></div><p id="move-message" class="hint" role="status"></p>';
movePanel.hidden=true;
$('diagram').before(movePanel);
const transferNotice=el('section',{id:'transfer-notice',class:'transfer-notice',role:'status','aria-live':'polite','aria-atomic':'true','aria-label':'Compatible piece found'});transferNotice.hidden=true;document.body.append(transferNotice);
function clearTransferSuggestion(){manual.pending=null;transferNotice.hidden=true;transferNotice.replaceChildren();}
function offerTransfer(){
 clearTransferSuggestion();if(dirty)return;const proposal=ManualGeometry.refillEarlierSheets(result,state.kerf,p=>state.rotate&&state.parts[p.groupId]?.allowRotate===true,[],1);if(!proposal.transfers.length)return;
 const transfer=proposal.transfers[0],piece=proposal.result.sheets[transfer.to-1].pieces.find(p=>p.id===transfer.id);manual.pending={...proposal,baseline:JSON.stringify(result),signature:layoutSignature()};
 transferNotice.append(el('strong',{},'Compatible piece found'),el('p',{},(piece.label||'Part')+' · '+dimension(piece.w)+' × '+dimension(piece.h)+' cm fits the empty space on Sheet '+transfer.to+'. Move it from Sheet '+transfer.from+'?'));
 const actions=el('div',{class:'transfer-notice-actions'}),approve=el('button',{type:'button'},'Move piece'),dismiss=el('button',{type:'button'},'Not now');approve.onclick=approveTransfer;dismiss.onclick=()=>{clearTransferSuggestion();moveFeedback('Suggested transfer dismissed. Your layout is unchanged.');};actions.append(approve,dismiss);transferNotice.append(actions);transferNotice.hidden=false;
}
function approveTransfer(){
 const pending=manual.pending;if(!pending)return false;if(dirty||pending.baseline!==JSON.stringify(result)||pending.signature!==layoutSignature()){clearTransferSuggestion();moveFeedback('The layout changed. Move a part to check for a new match.');return false;}
 const transfer=pending.transfers[0];rememberManualChange();clearTransferSuggestion();result=pending.result;finishManualChange(transfer.id,'Moved '+(transfer.label||'part')+' from Sheet '+transfer.from+' to Sheet '+transfer.to+' after your approval.'+(pending.removedBoards?' The empty board was removed.':''));return true;
}
function layoutSignature(){return JSON.stringify([state.stock,state.parts,state.kerf,state.rotate]);}
function storeManual(){state.manualLayout={signature:layoutSignature(),result:JSON.parse(JSON.stringify(result))};try{localStorage.setItem('sheetwise',JSON.stringify(state));}catch{manual.message+=' Browser storage is full; save a project file to keep these adjustments.';}}
function selectManualPart(index){manual.index=index;const s=result.sheets[selected],p=s?.pieces[index];if(p){$('move-part').value=index;$('move-x').value=dimension(p.x);$('move-y').value=dimension(p.y);}document.querySelectorAll('#diagram .cut-part').forEach((node,i)=>node.classList.toggle('move-selected',manual.enabled&&i===index));}
function renderManual(){const s=result?.sheets[selected],enabled=manual.enabled&&!dirty&&!!s;$('move-mode').checked=manual.enabled;$('move-part').replaceChildren();s?.pieces.forEach((p,i)=>$('move-part').append(el('option',{value:i},(i+1)+'. '+p.label+' · '+dimension(p.w)+' × '+dimension(p.h)+' cm')));if(!s?.pieces[manual.index])manual.index=0;for(const id of ['move-part','move-x','move-y','apply-move'])$(id).disabled=!enabled;$('undo-move').disabled=dirty||!manual.history.length;$('reset-layout').disabled=!state.manualLayout;$('move-message').textContent=dirty?'Inputs changed. Optimize again before moving parts.':manual.message||'Move a part to find compatible pieces on later boards. Transfers wait for your approval.';selectManualPart(manual.index);$('diagram').classList.toggle('move-enabled',enabled);if(enabled)bindManualDrag();else document.querySelectorAll('#diagram .cut-part').forEach(node=>{node.onpointerdown=null;node.onkeydown=null;});}
function refreshManualStats(){const utilization=result.area?100*result.used/result.area:0;$('stats').replaceChildren();for(const [label,value,unit]of [['Material utilization',utilization.toFixed(1),'%'],['Sheets required',result.sheets.length,'sheets'],['Unused area',(100-utilization).toFixed(1),'%']]){const card=el('div',{class:'stat'}),strong=el('strong',{},value+' ');strong.append(el('span',{},unit));card.append(el('small',{},label),strong);$('stats').append(card);}}
function rememberManualChange(){manual.history.push({result:JSON.parse(JSON.stringify(result)),selected,index:manual.index});if(manual.history.length>40)manual.history.shift();}
function finishManualChange(pieceId,message){
 clearTransferSuggestion();for(let si=0;si<result.sheets.length;si++){const index=result.sheets[si].pieces.findIndex(p=>p.id===pieceId);if(index>=0){selected=si;manual.index=index;break;}}
 manual.message=message;$('status').textContent='Manually adjusted layout · '+result.sheets.length+' sheets · '+result.sheets.reduce((sum,s)=>sum+s.pieces.length,0)+' pieces placed';refreshManualStats();storeManual();draw();moveFeedback(manual.message);
 const undo=el('button',{type:'button',class:'transfer-undo'},'Undo move');undo.onclick=()=>{$('undo-move').onclick();moveFeedback(manual.message);};$('remnant-info').append(document.createTextNode(' '),undo);offerTransfer();
}
function applyManualMove(x,y){if(!manual.enabled||dirty)return;const sheet=result.sheets[selected],p=sheet?.pieces[manual.index];if(!p)return;if(Math.abs(x-p.x)<1e-7&&Math.abs(y-p.y)<1e-7)return;const proposed=ManualGeometry.proposeMove(sheet,manual.index,x,y,state.kerf);if(proposed.error){manual.message=proposed.error;renderManual();moveFeedback(proposed.error,true);return false;}rememberManualChange();const sheets=[...result.sheets];sheets[selected]=proposed.sheet;result=ManualGeometry.layoutWithSheets(result,sheets);finishManualChange(p.id,'Moved '+p.label+' to X '+dimension(x)+', Y '+dimension(y)+' cm.'+(proposed.sheet.isGuillotine?' Layout checked.':' Free placement accepted.'));return true;}
function snapMove(sheet,index,x,y,tolerance,checkCuts=false){return ManualGeometry.snapPosition(sheet,index,x,y,state.kerf,tolerance,checkCuts);}
function moveFeedback(message,error=false){$('remnant-info').textContent=message;$('remnant-info').classList.toggle('move-error',error);}
function bindManualDrag(){const svg=$('diagram').querySelector('svg'),s=result.sheets[selected];if(!svg)return;svg.querySelectorAll('.cut-part').forEach((node,index)=>{node.setAttribute('role','button');node.setAttribute('aria-label','Move '+s.pieces[index].label+' piece '+(index+1));node.onkeydown=event=>{const offsets={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(!offsets[event.key])return;event.preventDefault();selectManualPart(index);const p=result.sheets[selected].pieces[index],step=event.shiftKey?1:.1,[dx,dy]=offsets[event.key];applyManualMove(p.x+dx*step,p.y+dy*step);};node.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();selectManualPart(index);svg.querySelectorAll('.move-ghost').forEach(ghost=>ghost.remove());const point=event=>{const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());},origin=point(event),matrix=svg.getScreenCTM(),tolerance=(event.pointerType==='touch'?18:12)/Math.max(.0001,Math.hypot(matrix.a,matrix.b)),p=s.pieces[index],ghost=document.createElementNS('http://www.w3.org/2000/svg','rect');for(const [k,v]of Object.entries({x:p.x,y:p.y,width:p.w,height:p.h,class:'move-ghost','pointer-events':'none'}))ghost.setAttribute(k,v);svg.append(ghost);node.setPointerCapture(event.pointerId);let target={x:p.x,y:p.y},dragged=false;const move=e=>{if(Math.hypot(e.clientX-event.clientX,e.clientY-event.clientY)>2)dragged=true;const at=point(e);target=snapMove(s,index,p.x+at.x-origin.x,p.y+at.y-origin.y,tolerance);const error=ManualGeometry.validatePosition(s,index,target.x,target.y,state.kerf);ghost.classList.toggle('snap-active',target.snapped&&!error);moveFeedback(error||(target.snapped?'Snapped to an edge · '+dimension(state.kerf*10)+' mm saw kerf preserved.':'Drag near another part or the sheet edge to snap.'),!!error);ghost.setAttribute('x',target.x);ghost.setAttribute('y',target.y);ghost.classList.toggle('invalid',!!ManualGeometry.validatePosition(s,index,target.x,target.y,state.kerf));$('move-x').value=dimension(target.x);$('move-y').value=dimension(target.y);};const cleanup=()=>{ghost.remove();node.removeEventListener('pointermove',move);node.removeEventListener('pointerup',up);node.removeEventListener('pointercancel',cancel);node.removeEventListener('lostpointercapture',cancel);};const up=e=>{move(e);const at=point(e);if(dragged)target=snapMove(s,index,p.x+at.x-origin.x,p.y+at.y-origin.y,tolerance,true);cleanup();if(dragged){const same=Math.abs(target.x-p.x)<1e-7&&Math.abs(target.y-p.y)<1e-7;if(same&&target.snapped&&!selected)moveFeedback('Snapped to the current edge. Drag farther away to release it.');else applyManualMove(target.x,target.y);}selectManualPart(manual.index);};const cancel=()=>{cleanup();selectManualPart(index);};node.addEventListener('pointermove',move);node.addEventListener('pointerup',up);node.addEventListener('pointercancel',cancel);node.addEventListener('lostpointercapture',cancel);};});}
$('move-mode').onchange=()=>{manual.enabled=$('move-mode').checked;draw();};$('move-part').onchange=()=>selectManualPart(Number($('move-part').value));$('apply-move').onclick=()=>applyManualMove(Number($('move-x').value),Number($('move-y').value));
$('undo-move').onclick=()=>{if(dirty)return;clearTransferSuggestion();const previous=manual.history.pop();if(!previous)return;if(previous.result){result=previous.result;selected=previous.selected;manual.index=previous.index;}else{result.sheets[previous.sheet]=previous.before;selected=previous.sheet;}manual.message='Last move undone.';$('status').textContent='Manually adjusted layout · '+result.sheets.length+' sheets · '+result.sheets.reduce((sum,s)=>sum+s.pieces.length,0)+' pieces placed';refreshManualStats();storeManual();draw();};
$('reset-layout').onclick=()=>run();
function restoreManualLayout(){const saved=state.manualLayout;if(!saved||saved.signature!==layoutSignature())return false;const sheets=ManualGeometry.restoreLayoutSheets(saved.result,result,state.parts,state.kerf,state.rotate);if(sheets===null)return false;result=ManualGeometry.layoutWithSheets(result,sheets);selected=Math.min(selected,Math.max(0,sheets.length-1));refreshManualStats();manual.message='Restored your manually adjusted layout.';$('status').textContent='Manually adjusted layout restored · '+result.sheets.reduce((t,s)=>t+s.pieces.length,0)+' pieces placed';return true;}
const manualDraw=draw;draw=function(){$('remnant-info').classList.remove('move-error');manualDraw();renderManual();};
const manualChanged=changed;changed=function(){clearTransferSuggestion();manualChanged();if($('move-message'))renderManual();};
const automaticRun=run;run=function(){clearTransferSuggestion();const saved=state.manualLayout;delete state.manualLayout;const ok=automaticRun();if(!ok){if(saved)state.manualLayout=saved;return false;}manual.enabled=true;manual.history=[];manual.message='Automatic layout ready. Drag a part to adjust its position.';renderManual();return true;};$('run').onclick=()=>run();
const manualLoad=loadProject;loadProject=function(candidate){const saved=candidate.manualLayout;manualLoad(candidate);if(saved){state.manualLayout=saved;if(restoreManualLayout()){storeManual();draw();}else{delete state.manualLayout;manual.message='Project opened; saved manual positions no longer match. Automatic layout shown.';renderManual();}}};
restoreManualLayout();draw();

